-- ===== U8 vocab 覆盖灌库(volume='9',43词)。分步跑。=====

SELECT 'U8 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U8';

DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U8';
SELECT 'U8 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U8';  -- 应0


SELECT 'U8 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U8';  -- 应43
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U8' GROUP BY word HAVING count(*)>1;  -- 查重应0行